(() => {
'use strict';
const D=window.PIPI_DATA, M=D.modules, root=document.getElementById('app');
const paths={robot:'robot',app:'app',cloud:'cloud',external:'external',vision:'vision'};
const navNames={overview:'项目总览',product:'产品概述',requirements:'产品需求',system:'系统总体架构',cloud:'皮皮猴云端',vision:'PiPi Vision',robot:'机器人端',app:'小程序 App 端',external:'外部云端',interfaces:'接口文档',models:'数据模型',progress:'开发进度'};
let route='overview', selected=null, mobileMenu=false, treeOpen=true, saved={}, storageAvailable=true;
try {const raw=JSON.parse(localStorage.getItem('pipi-status-v1')||'{}'); if(raw && typeof raw==='object') for(const [k,v] of Object.entries(raw)) if(M[k] && D.statuses[v]) saved[k]=v;} catch {storageAvailable=false;}
const escape=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const svg={home:'M3 10l9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',cloud:'M7 18a5 5 0 01-1-10 7 7 0 0113 2 4 4 0 01-1 8H7',robot:'M7 7h10a3 3 0 013 3v8a3 3 0 01-3 3H7a3 3 0 01-3-3v-8a3 3 0 013-3 M12 7V3 M8 12h.01 M16 12h.01 M8 17h8 M1 12v5 M23 12v5',app:'M7 2h10a2 2 0 012 2v16a2 2 0 01-2 2H7a2 2 0 01-2-2V4a2 2 0 012-2 M9 5h6 M11 19h2',globe:'M12 2a10 10 0 100 20 10 10 0 000-20 M2 12h20 M12 2c6 6 6 14 0 20-6-6-6-14 0-20',book:'M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3V4 M12 6v16',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',vision:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 100 6 3 3 0 000-6',voice:'M9 3h6v12H9z M5 11v2a7 7 0 0014 0v-2 M12 20v3',activity:'M2 12h5l3-8 4 16 3-8h5',steps:'M4 20h5v-5h5v-5h6V4',core:'M8 8h8v8H8z M9 2v6 M15 2v6 M9 16v6 M15 16v6 M2 9h6 M2 15h6 M16 9h6 M16 15h6',database:'M3 6c0-5 18-5 18 0s-18 5-18 0 M3 6v6c0 5 18 5 18 0V6 M3 12v6c0 5 18 5 18 0v-6',user:'M12 3a4 4 0 100 8 4 4 0 000-8 M4 22v-3a8 8 0 0116 0v3',target:'M12 2a10 10 0 100 20 10 10 0 000-20 M12 7a5 5 0 100 10 5 5 0 000-10 M12 10v4 M10 12h4',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',gateway:'M3 4h18v6H3z M3 14h18v6H3z M7 7h.01 M7 17h.01',chevron:'M9 5l7 7-7 7',close:'M5 5l14 14 M19 5L5 19',menu:'M3 6h18 M3 12h18 M3 18h18',link:'M10 13l4-4 M8 16l-2 2a4 4 0 01-6-6l5-5a4 4 0 016 0 M16 8l2-2a4 4 0 016 6l-5 5a4 4 0 01-6 0',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',check:'M4 12l5 5L20 6',warning:'M12 3L2 21h20L12 3 M12 9v5 M12 17h.01'};
function icon(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${svg[n]||svg.grid}"/></svg>`;}
const status=id=>saved[id]||M[id].status;
const badge=id=>`<span class="badge ${status(id)}"><i></i>${D.statuses[status(id)]}</span>`;
function counts(){return Object.keys(D.statuses).map(s=>Object.keys(M).filter(id=>status(id)===s).length);}
function navLink(id,name,ic,sub=false){return `<a class="nav-item ${route===id?'active':''} ${sub?'sub':''}" href="#/${id}" ${route===id?'aria-current="page"':''}>${ic?icon(ic):'<span class="tree-line"></span>'}<span>${name}</span>${id==='system'?'<small>4</small>':''}</a>`;}
function sidebar(){return `<aside class="sidebar ${mobileMenu?'visible':''}"><a class="brand" href="#/overview"><span class="brandmark">P</span><span>皮皮猴 <b>PiPi</b><small>系统架构导航台</small></span></a><div class="workspace-label">PROJECT WORKSPACE <span>V0.1</span></div><nav aria-label="项目导航">${navLink('overview','项目总览','home')}<div class="nav-caption">产品与设计</div>${navLink('product','产品概述','book')}${navLink('requirements','产品需求','file')}<div class="nav-caption">架构与工程</div><div class="nav-tree-head">${navLink('system','系统架构','grid')}<button class="tree-toggle ${treeOpen?'open':''}" data-action="tree" aria-label="${treeOpen?'折叠':'展开'}架构导航" aria-expanded="${treeOpen}">${icon('chevron')}</button></div>${treeOpen?`<div class="tree-children">${navLink('robot','机器人端',null,true)}${navLink('app','小程序 App 端',null,true)}${navLink('cloud','皮皮猴云端',null,true)}${navLink('vision','PiPi Vision',null,true)}${navLink('external','外部云端',null,true)}</div>`:''}${navLink('interfaces','接口文档','link')}${navLink('models','数据模型','database')}${navLink('progress','开发进度','activity')}</nav><div class="sidebar-footer"><div class="project-avatar">P</div><div>PiPi 项目空间<small>架构原型 · 示例数据</small></div></div></aside>`;}
function crumbs(){let a=[['overview','项目总览']];if(['system','cloud','vision','robot','app','external'].includes(route))a.push(['system','系统架构']);if(route==='vision')a.push(['cloud','皮皮猴云端']);if(route!=='overview'&&route!=='system')a.push([route,navNames[route]]);return a.map(([id,name],i)=>`${i?icon('chevron'):''}<a href="#/${id}" ${i===a.length-1?'aria-current="page"':''}>${name}</a>`).join('');}
function header(title,desc,label,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1 tabindex="-1">${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function moduleCard(id,compact=false){const m=M[id];return `<article class="module-card ${id==='cloud'?'accent':''} ${compact?'compact':''}"><a href="#/${paths[id]||route}" ${paths[id]?'':'data-inspect="'+id+'"'} class="card-main"><div class="card-top"><span class="module-icon ${id==='cloud'?'teal':''}">${icon(m.icon)}</span>${badge(id)}</div><h3>${m.name}</h3><span class="english">${m.en}</span><p>${m.role}</p><div class="card-bottom"><span>${paths[id]?'查看内部架构':'查看模块详情'}</span><span class="level-tag">${id==='vision'?'L3':'L2'}</span></div></a><button class="detail-button" data-inspect="${id}" aria-label="查看${m.name}职责">${icon('file')} 职责</button></article>`;}
function overview(){const c=counts();return `${header('从全局，进入每一个细节','儿童多模态互动教学智能体平台','PIPI / PROJECT OVERVIEW', '<span class="version">架构版本 <b>V0.1</b></span>')}<div class="overview-banner"><div><span class="eyebrow">ARCHITECTURE EXPLORER</span><h2>一个平台，四个协作系统</h2><p>感知、决策、交互与模型能力，在这里连接。</p><a class="button primary" href="#/system">探索总体架构 ${icon('grid')}</a></div><div class="mini-map" aria-label="四端协作示意"><span>${icon('robot')}机器人</span><i></i><strong>${icon('cloud')}PiPi Cloud</strong><i></i><span>${icon('app')}App</span><small>感知 · 决策 · 教学 · 交互</small></div></div><div class="section-heading"><h2>系统入口 <small>4 个系统</small></h2><span>点击进入下一层架构</span></div><div class="system-cards">${['robot','app','cloud','external'].map(id=>moduleCard(id)).join('')}</div><div class="overview-bottom"><section class="panel"><div class="section-heading"><h2>架构层级</h2><span class="muted">由整体到实现</span></div><div class="layer-trail"><a href="#/overview"><b>L0</b><span>项目总览</span></a>${icon('chevron')}<a href="#/system"><b>L1</b><span>系统架构</span></a>${icon('chevron')}<a href="#/cloud"><b>L2</b><span>云端服务</span></a>${icon('chevron')}<a href="#/vision"><b>L3</b><span>模块实现</span></a></div></section><section class="panel"><div class="section-heading"><h2>模块状态</h2><a href="#/progress">查看进度</a></div><div class="status-counts">${Object.keys(D.statuses).map((s,i)=>`<div><strong>${c[i]}</strong><span class="badge ${s}"><i></i>${D.statuses[s]}</span></div>`).join('')}</div></section></div><div class="notice">${icon('warning')}架构和接口基于 V0.1 设计；状态为可修改的示例。硬件形态与具体接口仍需项目确认。</div>`;}
function node(id,cls=''){const m=M[id];return `<div class="graph-node ${cls} ${selected===id?'selected':''}"><button class="node-body" ${paths[id]?`data-go="${paths[id]}"`:`data-inspect="${id}"`}><span class="node-icon">${icon(m.icon)}</span><span><strong>${m.name}</strong><small>${m.en}</small></span>${paths[id]?'<span class="depth-indicator">进入</span>':''}</button><div class="node-meta">${badge(id)}<button data-inspect="${id}" aria-label="${m.name}模块详情">${icon('file')}</button></div></div>`;}
function legend(){return `<div class="diagram-footer"><span><i class="line-key"></i>核心业务流 <i class="line-key dashed"></i>能力与数据依赖</span><span>点击节点查看详情 · 标有“进入”的节点可下钻</span></div>`;}
function system(){return `${header('系统总体架构','每个系统各司其职，通过云端连接感知、教学与执行。','L1 / SYSTEM ARCHITECTURE')}<div class="graph-panel"><div class="graph-bar"><span>${icon('grid')} 四端协作架构</span><span class="version">V0.1</span></div><div class="system-graph"><div class="external-node">${node('external')}</div><div class="external-connector"><span>AI 请求 ↑ &nbsp; ↓ 模型结果</span></div><div class="system-row">${node('robot')}<div class="connection horizontal"><span>感知数据 →</span><div></div><span>← 设备控制</span></div>${node('cloud','core-node')}<div class="connection horizontal"><span>UI / 教学状态 →</span><div></div><span>← 用户操作</span></div>${node('app')}</div></div>${legend()}</div><div class="section-heading"><h2>六组核心数据流</h2><span>点击对应系统继续探索</span></div>${interfacesTable(false)}<div class="notice">${icon('warning')}待确认：Camera / Microphone / Speaker 的物理归属。当前按独立机器人硬件组织职责。</div>`;}
function cloud(){return `${header('皮皮猴云端','接入感知与交互，形成教学策略，再由 Agent Core 统一决策。','L2 / PIPI CLOUD', '<a class="button" href="#/system">返回总体架构</a>')}<div class="graph-panel"><div class="graph-bar"><span>${icon('cloud')} 云端内部架构</span><a href="#/vision" class="inline-link">探索 PiPi Vision</a></div><div class="cloud-graph"><div class="layer-label">01 <span>统一接入</span></div><div class="graph-layer single">${node('gateway')}</div><div class="graph-flow">请求与数据 ↓</div><div class="layer-label">02 <span>感知与交互</span></div><div class="graph-layer two">${node('vision','vision-node')}${node('voice')}</div><div class="graph-flow">感知事件 / 对话状态 ↓</div><div class="layer-label">03 <span>教学编排</span></div><div class="graph-layer three">${node('activity')}${node('step')}${node('teaching')}</div><div class="graph-flow">上下文 + 教学建议 ↓</div><div class="layer-label">04 <span>统一决策</span></div><div class="graph-layer single">${node('core','core-node')}</div><div class="decision-label">行为决策 · 语音播报 / App 表现 / 设备控制</div><div class="support-layer"><div class="layer-label">05 <span>知识与基础服务</span></div><div class="graph-layer four">${['knowledge','memory','user','device'].map(id=>node(id)).join('')}</div></div></div>${legend()}</div><div class="notice">${icon('core')}Agent Core 聚合各服务状态并统一决策；图中向下连线表示信息汇聚，底层虚线表示共享服务依赖。</div>`;}
function vision(){return `${header('PiPi Vision','从视频帧到对象轨迹，再到可用于教学的视觉证据。','L3 / VISION SERVICE', '<a class="button" href="#/cloud">返回云端架构</a>')}<div class="vision-summary"><div>${icon('vision')}<span><strong>Vision Service</strong><small>关联项目：PiPi Vision</small></span></div>${badge('vision')}<button class="button" data-inspect="vision">服务职责</button></div><div class="graph-panel"><div class="graph-bar"><span>${icon('activity')} 视觉处理流水线</span><span class="muted">输入：Video Frame + Timestamp</span></div><div class="vision-pipeline"><div class="pipeline-label">VIDEO FRAME</div>${node('detection')}<div class="pipeline-connector"><span>Bounding Box · Class · Confidence</span></div>${node('tracker')}<div class="pipeline-connector"><span>Object ID · Track · State</span></div>${node('vision-activity')}<div class="pipeline-connector"><span>Visual Event · 按规则触发</span></div>${node('vlm')}<div class="pipeline-label output">VISION STATE / EVENT / VLM RESULT</div></div>${legend()}</div><div class="section-heading"><h2>实现组件</h2><span>职责、输入输出与依赖</span></div><div class="implementation-grid">${['detection','tracker','vision-activity','vlm'].map(id=>`<button class="implementation-item" data-inspect="${id}"><span>${icon(M[id].icon)}<strong>${M[id].name}</strong></span><p>${M[id].children.join(' · ')}</p>${badge(id)}</button>`).join('')}</div><div class="notice">${icon('link')}Vision Activity Engine 只产出视觉事件。跨模态活动与教学步骤由云端 Activity Engine 和 Step Manager 管理。</div>`;}
function subsystem(id){const m=M[id];return `${header(m.name,m.role,'L2 / '+m.en.toUpperCase(),'<a class="button" href="#/system">返回总体架构</a>')}<div class="subsystem-intro panel"><span class="module-icon teal">${icon(m.icon)}</span><div><h2>${m.en}</h2><p>${m.role}</p></div>${badge(id)}<button class="button" data-inspect="${id}">系统详情</button></div><div class="section-heading"><h2>内部职责分区</h2><span>V0.1 功能划分</span></div><div class="functional-grid">${m.children.map((s,i)=>`<article class="panel"><span class="eyebrow">MODULE ${String(i+1).padStart(2,'0')}</span><h2>${s}</h2><p>${subtexts[id][i]}</p><span class="badge planned"><i></i>规划中</span></article>`).join('')}</div>${m.note?`<div class="notice">${icon('warning')}${m.note}</div>`:''}`;}
const subtexts={robot:['采集 Camera / Microphone 数据，感知人物和环境。','语音唤醒、人物跟随，以及本地安全策略。','执行云台、电机和舵机动作，播放音频。','维护设备状态、心跳、网络配置和 OTA。'],app:['皮皮猴形象、嘴型、眼神、表情及状态动画。','展示当前步骤、教学提示和活动进度。','活动列表与详情，支持开始、暂停和退出。','儿童与家长账户、学习记录和成长历史。','设备绑定、在线状态和设备设置。'],external:['提供实时语音识别、语言推理与语音合成。','处理高级语言推理与教学内容生成。','提供按需场景理解与视觉语义分析。','声纹识别、内容安全等辅助能力。','提供对象存储、内容分发与运行日志。']};
function interfacesTable(full=true){return `<div class="table-panel"><table><thead><tr><th>数据流方向</th><th>核心内容</th><th>交互类型</th>${full?'<th>关联模块</th>':''}</tr></thead><tbody>${D.interfaces.map(row=>`<tr><td>${row[0]}</td><td><code>${row[1]}</code></td><td>${row[2]}</td>${full?'<td>'+row[3]+'</td>':''}</tr>`).join('')}</tbody></table></div>`;}
function docs(){if(route==='product')return `${header('产品概述','皮皮猴是面向儿童的多模态互动教学智能体平台。','PRODUCT / OVERVIEW')}<div class="product-statement panel"><span class="eyebrow">PIPI PLATFORM</span><h2>看到孩子的操作，理解当前情境，<br>在合适的时刻给予引导。</h2><p>机器人感知与执行，App 呈现互动，云端组织教学，外部模型提供智能能力。</p></div><div class="functional-grid">${[['感知现实世界','视频、音频和设备状态共同构成会话上下文。'],['组织教学过程','活动和步骤管理形成有序、可追踪的教学流程。'],['主动提供帮助','结合视觉证据、当前步骤和历史记忆生成提示。']].map(([a,b])=>`<article class="panel"><h2>${a}</h2><p>${b}</p></article>`).join('')}</div><div class="notice">${icon('file')}本页为产品说明骨架，可随真实需求和硬件方案继续补充。</div>`;
if(route==='requirements')return `${header('产品需求','将产品能力映射到负责它的系统与服务。','PRODUCT / REQUIREMENTS')}<div class="table-panel"><table><thead><tr><th>能力</th><th>预期行为</th><th>负责模块</th><th>设计状态</th></tr></thead><tbody>${[['多模态感知','识别教学对象与操作状态','vision'],['实时语音互动','接收儿童语音，生成对话与播报','voice'],['教学流程','支持活动选择、步骤推进与完成判断','step'],['主动引导','长时间未操作时提供适当提示','core'],['设备管理','设备绑定、状态查询与配置同步','device'],['数字人表现','根据 UI 和教学状态呈现表情与动画','app']].map(([a,b,id])=>`<tr><td>${a}</td><td>${b}</td><td><button class="text-button" data-inspect="${id}">${M[id].name}</button></td><td><span class="badge planned"><i></i>待细化</span></td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('file')}需求为架构映射草案，验收标准、优先级和版本计划待补充。</div>`;
if(route==='interfaces')return `${header('接口文档','以六组核心数据流作为接口设计的起点。','ENGINEERING / INTERFACES')}${interfacesTable()}<div class="notice">${icon('file')}当前为接口职责草案。协议、路径、鉴权、错误码与消息格式尚未定稿。</div>`;
return `${header('数据模型','跨模块协作所需的核心实体与状态。','ENGINEERING / DATA MODELS')}<div class="model-grid">${D.models.map(([a,b,c])=>`<article class="panel model-card"><span class="module-icon">${icon('database')}</span><h2>${a}</h2><p>${c}</p><div class="field-list">${b.split(' · ').map(s=>`<code>${s}</code>`).join('')}</div><small>建议字段 · 待接口评审</small></article>`).join('')}</div>`;}
function progress(){const c=counts();return `${header('开发进度','按模块查看当前状态，修改后仅保存在当前浏览器。','ENGINEERING / PROGRESS','<button class="button" data-action="reset">恢复示例状态</button>')}<div class="progress-stats">${Object.keys(D.statuses).map((s,i)=>`<div class="panel"><span class="badge ${s}"><i></i>${D.statuses[s]}</span><strong>${c[i]}<small>模块</small></strong></div>`).join('')}</div><div class="table-panel"><table><thead><tr><th>模块</th><th>所属项目</th><th>当前状态</th><th>状态调整</th></tr></thead><tbody>${Object.entries(M).map(([id,m])=>`<tr><td><button class="text-button" data-inspect="${id}">${m.name}</button>${id==='vision-activity'?'<small class="table-note">Vision 内部</small>':''}</td><td>${m.project}</td><td>${badge(id)}</td><td><select aria-label="${m.name}${id==='vision-activity'?'视觉':''}状态" data-status="${id}">${Object.entries(D.statuses).map(([s,n])=>`<option value="${s}" ${s===status(id)?'selected':''}>${n}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('file')}这些状态是原型示例，不是已验证的开发进度。${storageAvailable?'状态修改仅在当前浏览器生效。':'浏览器存储不可用，状态修改仅在当前会话生效。'}</div>`;}
function detail(){if(!selected)return '';const id=selected,m=M[id];return `<div class="detail-backdrop" data-action="close-detail"></div><aside class="detail-panel" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1"><div class="detail-head"><span class="eyebrow">MODULE DETAILS</span><button class="icon-button" data-action="close-detail" aria-label="关闭模块详情">${icon('close')}</button></div><span class="module-icon teal">${icon(m.icon)}</span><h2 id="detail-title">${m.name}</h2><p class="detail-en">${m.en} · ${m.project}</p>${badge(id)}<section><h3>职责</h3><p>${m.role}</p></section><section><h3>输入 <span>INPUT</span></h3><ul>${m.input.map(s=>`<li>${s}</li>`).join('')}</ul></section><section><h3>输出 <span>OUTPUT</span></h3><ul>${m.output.map(s=>`<li>${s}</li>`).join('')}</ul></section><section><h3>依赖模块</h3><div class="chips">${m.dependencies.length?m.dependencies.map(k=>`<button data-inspect="${k}">${M[k].name}</button>`).join(''):'<span class="muted">无已声明的内部依赖</span>'}</div></section><section><h3>子模块</h3><div class="child-list">${m.children.map(k=>M[k]?`<button data-inspect="${k}">${M[k].name}${icon('chevron')}</button>`:`<div>${k}</div>`).join('')}</div></section><section><h3>当前状态</h3><select data-status="${id}" aria-label="修改${m.name}状态">${Object.entries(D.statuses).map(([s,n])=>`<option value="${s}" ${s===status(id)?'selected':''}>${n}</option>`).join('')}</select><small class="storage-note">示例状态 · ${storageAvailable?'仅保存到当前浏览器':'仅在当前会话生效'}</small></section><section><h3>关联项目</h3><div class="project-ref">${icon('grid')}${m.project}<small>尚未关联仓库链接</small></div></section>${m.note?`<div class="notice">${icon('warning')}${m.note}</div>`:''}${paths[id]?`<a class="button primary full" href="#/${paths[id]}">进入内部架构</a>`:''}</aside>`;}
function render(){const content=route==='overview'?overview():route==='system'?system():route==='cloud'?cloud():route==='vision'?vision():['robot','app','external'].includes(route)?subsystem(route):route==='progress'?progress():docs();root.innerHTML=`${mobileMenu?'<button class="menu-backdrop" data-action="menu" aria-label="关闭导航"></button>':''}${sidebar()}<div class="main-shell"><header class="topbar"><button class="icon-button mobile-toggle" data-action="menu" aria-label="打开导航" aria-expanded="${mobileMenu}">${icon('menu')}</button><div class="breadcrumbs">${crumbs()}</div><span class="topbar-label">${icon('grid')} Architecture workspace</span></header><main id="main-content">${content}<footer class="page-footer"><span>PiPi · 系统架构导航台</span><span>V0.1 / 可扩展架构原型</span></footer></main></div>${detail()}`;document.title=`${navNames[route]} · 皮皮猴 PiPi`;}
function readRoute(){const next=location.hash.replace(/^#\/?/,'')||'overview';route=navNames[next]?next:'overview';selected=null;mobileMenu=false;render();window.scrollTo(0,0);}
let lastFocus=null;
function inspect(id){if(!M[id])return;lastFocus=document.activeElement;selected=id;render();root.querySelector('.detail-panel').focus();}
function closeDetail(){selected=null;render();const key=lastFocus?.dataset?.inspect;const target=key&&root.querySelector(`[data-inspect="${key}"]`);(target||root.querySelector('h1'))?.focus();}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.className='show';setTimeout(()=>el.className='',2500);}
root.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-go],[data-inspect]');if(!target)return;if(target.dataset.inspect){e.preventDefault();inspect(target.dataset.inspect);return;}if(target.dataset.go){location.hash='/'+target.dataset.go;return;}const action=target.dataset.action;if(action==='tree'){treeOpen=!treeOpen;render();root.querySelector('.tree-toggle')?.focus();}if(action==='menu'){mobileMenu=!mobileMenu;render();}if(action==='close-detail')closeDetail();if(action==='reset'){saved={};try{localStorage.removeItem('pipi-status-v1');}catch{storageAvailable=false;}render();toast('已恢复示例状态');}});
root.addEventListener('change',e=>{if(!e.target.dataset.status)return;const id=e.target.dataset.status;if(!M[id]||!D.statuses[e.target.value])return;saved[id]=e.target.value;try{localStorage.setItem('pipi-status-v1',JSON.stringify(saved));}catch{storageAvailable=false;}render();root.querySelector(`[data-status="${id}"]`)?.focus();toast(storageAvailable?'状态已保存到当前浏览器':'状态已更新，浏览器存储不可用');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(selected)closeDetail();else if(mobileMenu){mobileMenu=false;render();}}if(e.key==='Tab'&&selected){const panel=root.querySelector('.detail-panel');const els=[...panel.querySelectorAll('button,a,select')];const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===panel)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',readRoute);readRoute();
})();
